#include <bits/stdc++.h>

using namespace std;

#define fore(i, s, e) for(int i = s; i < e; i++)
#define pb push_back
#define ALL(a) a.begin(), a.end()
#define SZ(a) ((int)a.size())
#define mset(a, b) memset(a, b, sizeof(a))
#define fst first
#define snd second

typedef long long ll;

typedef int tf;
typedef int tc;
const tf INF=1e9;
struct MCF{
	int n;
	vector<tc> prio, pot; vector<tf> curflow; vector<int> prevedge,prevnode;
	priority_queue<pair<tc, int>, vector<pair<tc, int>>, greater<pair<tc, int>>> q;
	struct edge{int to, rev; tf f, cap; tc cost;};
	vector<vector<edge>> g;
	MCF(int n):n(n),prio(n),curflow(n),prevedge(n),prevnode(n),pot(n),g(n){}
	void add_edge(int s, int t, tf cap, tc cost) {
    // cout << s << " " << t << " " << cap << endl;
		g[s].pb((edge){t,SZ(g[t]),0,cap,cost});
		g[t].pb((edge){s,SZ(g[s])-1,0,0,-cost});
	}
	pair<tf,tc> get_flow(int s, int t) {
		tf flow=0; tc flowcost=0;
    // cout << s << " " << t << endl;
		while(1){
			q.push({0, s});
			fill(ALL(prio),INF); 
			prio[s]=0; curflow[s]=INF;
			while(!q.empty()) {
				auto cur=q.top();
				tc d=cur.fst;
        int u=cur.snd;
				q.pop();
				if(d!=prio[u]) continue;
				for(int i=0; i<SZ(g[u]); ++i) {
					edge &e=g[u][i];
					int v=e.to;
					if(e.cap<=e.f) continue;
					tc nprio=prio[u]+e.cost+pot[u]-pot[v];
					if(prio[v]>nprio) {
						prio[v]=nprio;
						q.push({nprio, v});
						prevnode[v]=u; prevedge[v]=i;
						curflow[v]=min(curflow[u], e.cap-e.f);
					}
				}
			}
			if(prio[t]==INF) break;
			fore(i,0,n) pot[i]+=prio[i];
			tf df=min(curflow[t], INF-flow);
			flow+=df;
			for(int v=t; v!=s; v=prevnode[v]) {
				edge &e=g[prevnode[v]][prevedge[v]];
				e.f+=df; g[v][e.rev].f-=df;
				flowcost+=df*e.cost;
			}
		}
		return {flow,flowcost};
	}
};

int T = 150; // I'm supposing this works

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
  int N = n*T;
  MCF mcf(N + 2);
  fore(i, 0, n) fore(j, 0, T - 1) {
    mcf.add_edge(i * T + j, i * T + j + 1, INF, c); // Wait a minute on this city
  }
  fore(i, 0, T) mcf.add_edge(i, N + 1, INF, 0); // Arrive to city 0 on time i
  fore(i, 0, k) {
    int x; cin >> x; x--;
    mcf.add_edge(N, x * T, 1, 0); // One person in city x at time 0
  }
  fore(i, 0, m) {
    int x, y; cin >> x >> y; x--, y--;
    fore(j, 0, T - 1) { // for each time
      int cur = 1;
      fore(_, 0, k) { // k different people can go there
        mcf.add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
        mcf.add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
        cur += 2; // squared cost
      }
    }
  }
  auto p = mcf.get_flow(N, N + 1);
  assert(p.fst == k); 
  cout << p.snd << endl;
  return 0;
}
